int feb_can_lvpdb_heartbeat_pack(
    uint8_t *dst_p,
    const struct feb_can_lvpdb_heartbeat_t *src_p,
    size_t size)
{
    if (size < 2u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 2);

    dst_p[0] |= pack_left_shift_u8(src_p->tps_init_failed, 0u, 0x01u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_lv_poll_failed, 1u, 0x02u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_sh_poll_failed, 2u, 0x04u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_af1_af2_poll_failed, 3u, 0x08u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_cp_poll_failed, 4u, 0x10u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_rf_poll_failed, 5u, 0x20u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_lv_power_not_good, 6u, 0x40u);
    dst_p[0] |= pack_left_shift_u8(src_p->tps_sh_power_not_good, 7u, 0x80u);
    dst_p[1] |= pack_left_shift_u8(src_p->tps_af1_af2_power_not_good, 0u, 0x01u);
    dst_p[1] |= pack_left_shift_u8(src_p->tps_cp_power_not_good, 1u, 0x02u);
    dst_p[1] |= pack_left_shift_u8(src_p->tps_rf_power_not_good, 2u, 0x04u);
    dst_p[1] |= pack_left_shift_u8(src_p->dash_state_stale, 3u, 0x08u);

    return (2);
}

int feb_can_lvpdb_heartbeat_unpack(
    struct feb_can_lvpdb_heartbeat_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    if (size < 2u) {
        return (-EINVAL);
    }

    dst_p->tps_init_failed = unpack_right_shift_u8(src_p[0], 0u, 0x01u);
    dst_p->tps_lv_poll_failed = unpack_right_shift_u8(src_p[0], 1u, 0x02u);
    dst_p->tps_sh_poll_failed = unpack_right_shift_u8(src_p[0], 2u, 0x04u);
    dst_p->tps_af1_af2_poll_failed = unpack_right_shift_u8(src_p[0], 3u, 0x08u);
    dst_p->tps_cp_poll_failed = unpack_right_shift_u8(src_p[0], 4u, 0x10u);
    dst_p->tps_rf_poll_failed = unpack_right_shift_u8(src_p[0], 5u, 0x20u);
    dst_p->tps_lv_power_not_good = unpack_right_shift_u8(src_p[0], 6u, 0x40u);
    dst_p->tps_sh_power_not_good = unpack_right_shift_u8(src_p[0], 7u, 0x80u);
    dst_p->tps_af1_af2_power_not_good = unpack_right_shift_u8(src_p[1], 0u, 0x01u);
    dst_p->tps_cp_power_not_good = unpack_right_shift_u8(src_p[1], 1u, 0x02u);
    dst_p->tps_rf_power_not_good = unpack_right_shift_u8(src_p[1], 2u, 0x04u);
    dst_p->dash_state_stale = unpack_right_shift_u8(src_p[1], 3u, 0x08u);

    return (0);
}

