        printf_fn("0x%02X  brake  present=%d  last_rx_ms=%lu  rx_count=%lu\r\n", (unsigned)0x09, (int)feb_can_db.brake.meta.present, (unsigned long)feb_can_db.brake.meta.last_rx_ms, (unsigned long)feb_can_db.brake.meta.rx_count);
