const char *BMS_State_Name(BMS_State_t value)
{
    switch (value)
    {
    case BMS_STATE_BOOT: return "BOOT";
    case BMS_STATE_LV_POWER: return "LV_POWER";
    case BMS_STATE_BUS_HEALTH_CHECK: return "BUS_HEALTH_CHECK";
    case BMS_STATE_PRECHARGE: return "PRECHARGE";
    case BMS_STATE_ENERGIZED: return "ENERGIZED";
    case BMS_STATE_DRIVE: return "DRIVE";
    case BMS_STATE_BATTERY_FREE: return "BATTERY_FREE";
    case BMS_STATE_CHARGER_PRECHARGE: return "CHARGER_PRECHARGE";
    case BMS_STATE_CHARGING: return "CHARGING";
    case BMS_STATE_BALANCE: return "BALANCE";
    case BMS_STATE_FAULT_CELL_OVERVOLTAGE: return "FAULT_CELL_OVERVOLTAGE";
    case BMS_STATE_FAULT_CELL_UNDERVOLTAGE: return "FAULT_CELL_UNDERVOLTAGE";
    case BMS_STATE_FAULT_CELL_OVERTEMP: return "FAULT_CELL_OVERTEMP";
    case BMS_STATE_FAULT_CELL_UNDERTEMP: return "FAULT_CELL_UNDERTEMP";
    case BMS_STATE_FAULT_TEMP_SENSOR_LOSS: return "FAULT_TEMP_SENSOR_LOSS";
    case BMS_STATE_FAULT_ADBMS_INIT: return "FAULT_ADBMS_INIT";
    case BMS_STATE_FAULT_ADBMS_TIMEOUT: return "FAULT_ADBMS_TIMEOUT";
    case BMS_STATE_FAULT_IVT_TIMEOUT: return "FAULT_IVT_TIMEOUT";
    case BMS_STATE_FAULT_OVERCURRENT: return "FAULT_OVERCURRENT";
    case BMS_STATE_FAULT_IMD: return "FAULT_IMD";
    case BMS_STATE_FAULT_BSPD: return "FAULT_BSPD";
    case BMS_STATE_FAULT_CONTACTOR_MISMATCH: return "FAULT_CONTACTOR_MISMATCH";
    case BMS_STATE_FAULT_BALANCE_HV_ACTIVE: return "FAULT_BALANCE_HV_ACTIVE";
    case BMS_STATE_FAULT_PRECHARGE_TIMEOUT: return "FAULT_PRECHARGE_TIMEOUT";
    case BMS_STATE_FAULT_PRECHARGE_TOO_FAST: return "FAULT_PRECHARGE_TOO_FAST";
    case BMS_STATE_FAULT_CHARGER_PRECHARGE_TIMEOUT: return "FAULT_CHARGER_PRECHARGE_TIMEOUT";
    case BMS_STATE_FAULT_SHUTDOWN_OPEN: return "FAULT_SHUTDOWN_OPEN";
    case BMS_STATE_FAULT_AIR_MINUS_OPEN: return "FAULT_AIR_MINUS_OPEN";
    case BMS_STATE_FAULT_CHARGER_HW: return "FAULT_CHARGER_HW";
    case BMS_STATE_FAULT_MANUAL: return "FAULT_MANUAL";
    case BMS_STATE_FAULT_IVT_VOLTAGE_NEGATIVE: return "FAULT_IVT_VOLTAGE_NEGATIVE";
    default: return "UNKNOWN";
    }
}
